import re

def parse(lines):
    skip = []
    recs = []
    used = []
    section = ''
    cur = None
    for i, l in enumerate(lines):
        s = l.strip()
        if not s:
            continue
        if l.startswith('Pygments version') or re.match(r'^[~=\-]{3,}$', s):
            skip.append(i)
            continue
        if not l.startswith('*') and not l[:1].isspace():
            m = re.match(r'^(\S.*?):\s*$', l)
            if m:
                section = m.group(1)
                skip.append(i)
                cur = None
                continue
        m = re.match(r'^\*\s+(.*?):?\s*$', l)
        if m:
            cur = {'section': section, 'names': m.group(1), 'description': '', 'filenames': ''}
            recs.append(cur)
            used.append(i)
            continue
        if cur is not None and l[:1].isspace():
            cur['description'] = (cur['description'] + ' ' + s).strip()
            used.append(i)
            continue
    for r in recs:
        m = re.search(r'\s*\(filenames ([^)]*)\)\s*$', r['description'])
        if m:
            r['filenames'] = m.group(1)
            r['description'] = r['description'][:m.start()].strip()
    blocks = []
    if recs:
        blocks.append({'name': 'entries', 'kind': 'table', 'lines': used, 'records': recs})
    return {'blocks': blocks, 'skip': skip}
